// ValidateProvenantAipResponseBody runs the validations defined on
// ProvenantAipResponseBody
func ValidateProvenantAipResponseBody(body *ProvenantAipResponseBody) (err error) {
	if body.UUID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("uuid", "body"))
	}
	if body.Name == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("name", "body"))
	}
	if body.Status == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("status", "body"))
	}
	if body.CreatedAt == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("created_at", "body"))
	}
	if body.Profile == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("profile", "body"))
	}
	if body.UUID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.uuid", *body.UUID, goa.FormatUUID))
	}
	if body.Status != nil {
		if !(*body.Status == "queued" || *body.Status == "processing" || *body.Status == "completed" || *body.Status == "error" || *body.Status == "canceled") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.status", *body.Status, []any{"queued", "processing", "completed", "error", "canceled"}))
		}
	}
	if body.CreatedAt != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.created_at", *body.CreatedAt, goa.FormatDateTime))
	}
	if body.Profile != nil {
		if !(*body.Profile == "files_and_metadata" || *body.Profile == "files_metadata_and_manifests" || *body.Profile == "original_and_extracted") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.profile", *body.Profile, []any{"files_and_metadata", "files_metadata_and_manifests", "original_and_extracted"}))
		}
	}
	return
}

